// GENERATED by tools/gen.mjs from specs/cards.json. Do not edit by hand.
// Card pv-07: No cookies and they still recognize you
// Card broken on purpose: its spec.md does not decide the answer, and this test keeps only a short hash of it.
import { test, assert, readSource, newContainer } from '../../lib/testkit.js';
import { cardProblems } from '../../lib/security.js';

const SPEC = {"id":"pv-07","category":"privacy","template":"choice","depends":[]};
const GAP = {"right":["d456f48b"],"wrong":[],"head":"the card picks option %s, but that is not the answer the test expects.","none":"the card does not accept any answer.","tail":" cards/pv-07/spec.md does not say which option is right: decide it from the prompt and the concept, write it in the spec (Field `answer`: \"…\") and run /demo-swarm --retry pv-07 (agents do not change specs)."};
const hash = (v) => {
  const s = SPEC.id + ':' + v;
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 0x01000193) >>> 0;
  return h.toString(16).padStart(8, '0');
};

let card = null;
let loadError = null;
try {
  card = (await import('./card.js')).default ?? null;
} catch (e) {
  loadError = e;
}

test('pv-07: card.js exists and loads', () => {
  assert.ok(card, 'cards/pv-07/card.js does not exist, has no default export or has an error: ' + (loadError?.message ?? ''));
});

if (card) {
  test('pv-07: follows the contract', () => {
    assert.equal(card.id, SPEC.id, 'wrong id');
    assert.equal(card.category, SPEC.category, 'wrong category');
    assert.equal(card.template, SPEC.template, 'must use the template ' + SPEC.template);
    assert.ok([1, 2, 3].includes(card.difficulty), 'difficulty must be 1, 2 or 3');
    assert.ok(typeof card.title === 'string' && card.title.length > 3, 'missing title');
    assert.ok(typeof card.explanation === 'string' && card.explanation.length > 10, 'missing explanation');
    assert.equal(typeof card.render, 'function');
    assert.equal(typeof card.validate, 'function');
  });

  async function accepted() {
    const c = newContainer();
    card.render(c, { submit: () => ({ correct: false }) });
    return Array.from(c.querySelectorAll('[data-option]'))
      .map((n) => ({ value: n.getAttribute('data-option'), text: (n.querySelector('.option-text') ?? n).textContent }))
      .filter((o) => card.validate(o.value))
      .map((o) => ({ value: o.value, key: o.value, label: o.value + ' (' + JSON.stringify(o.text.length > 70 ? o.text.slice(0, 69) + '…' : o.text) + ')' }));
  }

  test('pv-07: accepts the right answer', async () => {
    const found = await accepted();
    const keys = found.map((a) => hash(a.key));
    const message = (found.length ? GAP.head.replace('%s', () => found.slice(0, 6).map((a) => a.label).join(', ')) : GAP.none) + GAP.tail;
    assert.ok(found.length === 1 && keys[0] === GAP.right[0], message);
  });

  test('pv-07: rejects the wrong answers', () => {
    for (const w of ["","zz"]) assert.equal(card.validate(w), false, 'validate should not accept ' + JSON.stringify(w));
  });

  test('pv-07: draws the challenge and returns the answer', async () => {
    const answer = (await accepted())[0]?.value;
    const c = newContainer();
    let received;
    card.render(c, { submit: (r) => { received = r; return { correct: card.validate(r) }; } });
    assert.ok(c.textContent.includes(card.title), 'render must show the title');
    if (answer === undefined) return;
    c.querySelector('[data-option="' + answer + '"]').click();
    c.querySelector('.button-primary').click();
    assert.equal(received, answer, 'the interaction should return the right answer');
  });

  test('pv-07: safe source', async () => {
    const src = await readSource('./card.js', import.meta.url);
    assert.deepEqual(cardProblems(src), []);
    if (SPEC.depends.includes('lib-hash')) assert.match(src, /from\s+['"]\.\.\/\.\.\/lib\/hash\.js['"]/, 'this card must use ../../lib/hash.js');
  });
}
